let raw = $input.item.json.text || $input.item.json.output || $input.item.json.response || '';
raw = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let parsed = null;
let parseError = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
}

const fallback = {
  incident_category: "",
  description: "",
  context: "",
  date_time: "",
  ongoing: null,
  immediate_danger: null,
  relationship_to_person: "",
  user_support_preference: "",
  missing_information: []
};

const currentTurn = (parsed && typeof parsed === 'object') ? { ...fallback, ...parsed } : fallback;

const sessionId = $('02 Normalize Input').item.json.session_id;

// Accumulate structured data across conversation turns, keyed by session
const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const previous = staticData.sessions[sessionId] || fallback;

const isEmpty = (v) => v === null || v === undefined || v === "";

const merged = { ...fallback };
for (const key of Object.keys(fallback)) {
  if (key === 'missing_information') {
    merged[key] = (Array.isArray(currentTurn[key]) && currentTurn[key].length)
      ? currentTurn[key]
      : (previous[key] || []);
    continue;
  }
  merged[key] = !isEmpty(currentTurn[key]) ? currentTurn[key] : previous[key];
}

staticData.sessions[sessionId] = merged;

return {
  json: {
    ...merged,
    _parse_success: parsed !== null,
    _parse_error: parseError,
    _raw_ai_output: raw,
    user_message: $('02 Normalize Input').item.json.user_message,
    session_id: sessionId,
    ai_reply: $('03 AI Response').item.json.output || $('03 AI Response').item.json.text || ''
  }
};

const danger = $json.immediate_danger;
const ongoing = $json.ongoing;

let safety_level = "LOW/UNCLEAR CONCERN";

if (danger === true) {
  safety_level = "HIGH SAFETY CONCERN";
} else if (ongoing === true) {
  safety_level = "MODERATE CONCERN";
}

return {
  json: {
    ...$json,
    safety_level
  }
};

const d = $json;
let supportCategory = "a trusted person you feel comfortable talking to";
const nextSteps = [];

const cat = (d.incident_category || "").toLowerCase();

if (d.safety_level === "HIGH SAFETY CONCERN") {
  nextSteps.push("If you're in immediate danger, please try to get to a safer location if you can, and reach out to a trusted person or local emergency services.");
}

if (cat.includes("workplace")) {
  supportCategory = "your workplace HR or safeguarding contact";
} else if (cat.includes("educational")) {
  supportCategory = "your university or student support office";
} else if (cat.includes("stalking") || cat.includes("threat")) {
  supportCategory = "local authorities and a trusted person, given the pattern you've described";
} else if (cat.includes("sexual")) {
  supportCategory = "a counselor or a women's rights organization / NGO";
} else if (cat.includes("online") || cat.includes("cyber")) {
  supportCategory = "the platform's reporting tools, and a trusted person or NGO focused on online safety";
}

nextSteps.push(`Based on what you've shared, ${supportCategory} may be a good place to look into.`);
nextSteps.push("You could also consider reaching out to a counselor or mental health support if this has been weighing on you.");
nextSteps.push("Note: these are general suggestions, not a guarantee of protection or an official referral. Please verify the right local service for your situation.");

return {
  json: {
    ...d,
    support_category: supportCategory,
    suggested_next_steps: nextSteps.join(" ")
  }
};

const d = $json;

const userMessage = (d.user_message || "").toLowerCase().trim();

// Detect explicit report requests directly from the current user message
const wantsReport =
  /\b(generate|create|make|show|give|export|download)\b.{0,40}\b(report|summary)\b/i.test(userMessage) ||
  /\b(report|summary)\b.{0,40}\b(generate|create|make|show|give|export|download)\b/i.test(userMessage) ||
  /\bmy\s+(incident\s+)?report\b/i.test(userMessage);

// If this is NOT a report request, don't create report_text
if (!wantsReport) {
  return {
    json: {
      ...d,
      report_text: "",
      wants_report: false
    }
  };
}

const reportText = `### HerSafe AI Incident Report *(AI-generated draft — please review before saving or sharing)*

**Incident Category:** ${d.incident_category || 'Not yet determined'}

**Incident Description:** ${d.description || 'Not yet provided'}

**Date/Time:** ${d.date_time || 'Not yet provided'}

**Context/Location:** ${d.context || 'Not yet provided'}

**Ongoing:** ${
  d.ongoing === true
    ? 'Yes'
    : d.ongoing === false
      ? 'No'
      : 'Unknown'
}

**Immediate Safety Concern:** ${
  d.immediate_danger === true
    ? 'Yes'
    : d.immediate_danger === false
      ? 'No'
      : 'Unknown'
} (AI-generated assessment based only on what you shared — Safety Level: ${d.safety_level || 'Unknown'})

**Relationship to Person Involved:** ${d.relationship_to_person || 'Not yet provided'}

**Support Requested:** ${d.user_support_preference || 'Not yet specified'}

**Suggested Next Steps:** ${d.suggested_next_steps || 'To be added'}

---

This is a draft report generated from your conversation. You can edit, save, or share it however feels right for you. It has not been submitted anywhere.`;

return {
  json: {
    ...d,
    wants_report: true,
    report_text: reportText
  }
};

const d = $json;

let output = d.ai_reply || "I'm here with you — could you tell me a bit more about what happened?";

// Add safety check only when appropriate
if (d.safety_level === "HIGH SAFETY CONCERN") {
  output += "\n\nI want to gently check in — if you're in danger right now, please try to get somewhere safer if you can, and reach out to a trusted person or local emergency services. I'm here to keep talking whenever you're ready.";
}

// ONLY attach the incident report when the user explicitly requested it
if (d.wants_report === true && d.report_text) {
  output += "\n\n" + d.report_text;
}

return {
  json: {
    ...d,
    output
  }
};
